css:
[data-bz-section="hours-grid"] .bz-block { padding-block: 0 }
[data-bz-section="hours-grid"] .bz-block + .bz-block { padding-block-start: 0 }
/* The handoff runs this band straight on from the store block above it, with no top padding of its own. */
[data-bz-section="hours-grid"] > .bz-section { padding-top: 0 }
[data-bz-section="hours-grid"] .bz-row + .bz-row { margin-top: 0 }
[data-bz-section="hours-grid"] h2 { font-size: 34px; line-height: 1.7; margin: 0 0 40px }
/* Handoff .card + .hours: one bordered card per department, a ruled row per day. */
[data-bz-section="hours-grid"] .bz-row[data-bz-node^="hg-cards"] { gap: 24px }
[data-bz-section="hours-grid"] .bz-col[data-bz-node^="hg-card-"] { display: flex; flex-direction: column; gap: 8px; border: 1px solid var(--line); background: var(--card); padding: 30px 26px }
[data-bz-section="hours-grid"] [data-bz-node^="hg-card-h"] { order: -1 }
[data-bz-section="hours-grid"] [data-bz-node^="hg-card-h"] h3 { font-size: 20px; line-height: 1.7; font-weight: 800; margin: 0 0 10px }
/* Admin sends the week Sunday first; the handoff reads Monday to Sunday, so Sunday goes to the foot. */
[data-bz-section="hours-grid"] [data-bz-node^="hg-day-"]:nth-child(2) { order: 1 }
[data-bz-section="hours-grid"] [data-bz-node^="hg-day-"] p { display: flex; justify-content: space-between; gap: 18px; margin: 0; border-top: 1px solid var(--line); padding-top: 8px; font-size: 14px; line-height: 1.5 }
[data-bz-section="hours-grid"] [data-bz-node^="hg-day-"] strong { font-weight: 700; color: var(--ink) }
[data-bz-section="hours-grid"] [data-bz-node^="hg-day-"] small { font-size: inherit; color: var(--body-text); text-align: right }
[data-bz-section="hours-grid"] [data-bz-node="hg-note"] p { font-size: 14px; line-height: 1.7; color: var(--muted); margin: 22px 0 0; max-width: 860px }
@media (min-width: 641px) and (max-width: 1100px) { [data-bz-section="hours-grid"] .bz-col[data-bz-node^="hg-card-"] { grid-column: span 6 } }
@media (max-width: 640px) { [data-bz-section="hours-grid"] h2 { font-size: 26px } }
